package com.furryfemboy.item;
import com.furryfemboy.entity.MilkProjectile; import com.furryfemboy.registry.ModSounds; import net.minecraft.server.level.ServerLevel; import net.minecraft.sounds.SoundSource; import net.minecraft.world.InteractionHand; import net.minecraft.world.InteractionResultHolder; import net.minecraft.world.entity.LivingEntity; import net.minecraft.world.entity.player.Player; import net.minecraft.world.item.*; import net.minecraft.world.level.Level;
public class GodzillaWeaponItem extends Item {
 public GodzillaWeaponItem(Properties p){super(p);}
 @Override public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand){ ItemStack stack=player.getItemInHand(hand); if(player.getCooldowns().isOnCooldown(this)) return InteractionResultHolder.fail(stack); if(!level.isClientSide){ MilkProjectile shot=new MilkProjectile(level,player); shot.shootFromRotation(player,player.getXRot(),player.getYRot(),0,1.8f,1.0f); level.addFreshEntity(shot); level.playSound(null,player.blockPosition(),ModSounds.GODZILLA_SHOT.get(),SoundSource.PLAYERS,1f,1f); stack.hurtAndBreak(1,player,e->e.broadcastBreakEvent(hand)); } player.getCooldowns().addCooldown(this,12); return InteractionResultHolder.sidedSuccess(stack,level.isClientSide()); }
 public static void fire(LivingEntity owner){ if(owner.level().isClientSide)return; MilkProjectile p=new MilkProjectile(owner.level(),owner); p.shootFromRotation(owner,owner.getXRot(),owner.getYRot(),0,1.55f,1.5f); owner.level().addFreshEntity(p); owner.level().playSound(null,owner.blockPosition(),ModSounds.GODZILLA_SHOT.get(),SoundSource.HOSTILE,0.8f,1.1f); }
}
